(function () {
  document.querySelectorAll('[data-jwt-liquid-products]').forEach(function (root) {
    if (root.dataset.initialized) return;
    root.dataset.initialized = 'true';
    const button = root.querySelector('[data-role="load"]');
    const status = root.querySelector('[data-role="status"]');
    const list = root.querySelector('[data-role="products"]');
    const priceFormat = new Intl.NumberFormat(undefined, {style: 'currency', currency: 'USD'});
    button.addEventListener('click', async function () {
      button.disabled = true;
      root.setAttribute('aria-busy', 'true');
      status.textContent = 'Loading products…';
      list.replaceChildren();
      try {
        const response = await apiease.runRequest('jwt-liquid-product-summaries');
        let payload = response && response.data;
        if (typeof payload === 'string') payload = JSON.parse(payload);
        if (response.status !== 200 || !payload || payload.ok !== true || !Array.isArray(payload.products)) {
          throw new Error('Products unavailable');
        }
        if (!payload.products.every(function (product) {
          return product && Number.isInteger(product.id) && typeof product.title === 'string' && Number.isFinite(product.price);
        })) throw new Error('Invalid products');
        payload.products.slice(0, 3).forEach(function (product) {
          const item = document.createElement('li');
          const title = document.createElement('span');
          const price = document.createElement('span');
          title.textContent = product.title;
          price.dataset.role = 'price';
          price.textContent = priceFormat.format(product.price);
          item.append(title, price);
          list.append(item);
        });
        status.textContent = list.children.length ? 'Products loaded.' : 'No products are available.';
      } catch (_error) {
        list.replaceChildren();
        status.textContent = 'Unable to load products. Please try again.';
      } finally {
        button.disabled = false;
        root.removeAttribute('aria-busy');
      }
    });
  });
})();
